import math

def babylonian_squareroot(n, tolerance=1e-10):
    if n < 0:
        raise ValueError("Cannot compute square root of negative number")
    if n == 0:
        return 0.0
    x = n / 2.0 if n > 1 else 1.0
    while True:
        next_x = 0.5 * (x + n / x)
        if abs(next_x - x) < tolerance:
            return next_x
        x = next_x
